// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzzed parameters: _baseToken is the deciding value; _nft and numeric params are also fuzzed but unconstrained.
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep feeRate within allowed bounds but wide
        vm.assume(_feeRate <= type(uint16).max);
        // We must ensure feeRate <= 5000 to avoid revert from FeeRateTooHigh for many fuzz inputs.
        // But to keep test wide, only constrain when fuzz gives > 5000: then cap it by rewriting a local var used to call initialize.
        uint16 feeRateBound = _feeRate > 5000 ? 5000 : _feeRate;

        // Call initialize as an arbitrary caller (not the factory owner), it's public and can be called by any address
        // We call directly (no payable value) — initialize is nonpayable so fine.
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, feeRateBound, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: if initialize succeeded (ok==true) then c.baseToken() must equal the supplied _baseToken.
        // This is the single assertion. The reference contract satisfies it for all inputs; the mutant fails when _baseToken != address(0).
        if (ok) {
            assertTrue(c.baseToken() == _baseToken);
        } else {
            // If initialize reverted, we still must assert something that holds for reference for all inputs —
            // In the reference, initialize can revert only if already initialized or feeRate too high. Since we deployed fresh c in setUp, the only reason here is feeRateBound > 5000 (we capped) or other invariants — improbable. To keep single assert rule, assertTrue(true) is not allowed. So for the revert case we assert that c.initialized() == false (reference: if initialize reverted, initialized remains false).
            assertTrue(c.initialized() == false);
        }
    }
}

