pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzer supplies the _baseToken and _nft addresses and numeric params; keep domain wide
    function testFuzz_property(address _baseToken, address _nft, uint128 _vBase, uint128 _vNft, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolen, bool _payRoyalties) public {
        // keep feeRate admissible so initialize won't revert on FeeRateTooHigh
        _feeRate = uint16(bound(_feeRate, 0, 5000));

        // Make a low-overhead caller that can receive events; we call directly from this EOA
        // Capture the logs by calling initialize inside a low-level call so we can inspect returned logs

        // prepare calldata for initialize
        bytes memory data = abi.encodeWithSelector(
            C.initialize.selector,
            _baseToken,
            _nft,
            _vBase,
            _vNft,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolen,
            _payRoyalties
        );

        // perform the call and capture success and logs via try/catch using address(c).call
        (bool success, bytes memory returnData) = address(c).call(data);

        // Only consider cases where initialize returned successfully
        if (!success) {
            // If initialize reverted, the property is vacuously true for this input; just return
            return;
        }

        // After successful initialize, read the public nft getter
        address storedNft = c.nft();

        // Now parse the last emitted Initialize event from the transaction receipt's logs is not available here.
        // However we can reproduce what the event would contain deterministically: the Initialize event is
        // declared as: event Initialize(address indexed baseToken, address indexed nft, uint128 ...)
        // The mutant vs reference difference is that the reference sets nft before emit, so the nft getter equals
        // the nft argument; the mutant emits before setting nft so the nft getter may differ from the emitted argument.
        // We can instead assert the following single observable universal property that the reference satisfies:
        // After initialize returns, the contract's nft() getter equals the address passed as the second argument.
        // This is a single assertion that the reference always satisfies; the mutant will fail for some fuzz inputs.

        assertTrue(storedNft == _nft);
    }
}

